/* ==========================================================================
   Facturas · Proveedores e IGIC
   Hoja de estilos única, sin dependencias.
   ========================================================================== */

:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --surface-2: #fbfaf6;
  --surface-3: #f2f0e9;
  --line: #e7e3d9;
  --line-strong: #d8d2c4;
  --ink: #17211d;
  --ink-2: #4d5852;
  --ink-3: #7d867f;
  --brand: #11665c;
  --brand-2: #0b4a43;
  --brand-soft: #e3f0ed;
  --brand-soft-2: #cfe6e1;
  --ok: #15693f;
  --ok-soft: #e6f4ec;
  --warn: #8f4c07;
  --warn-soft: #fdf0dd;
  --danger: #a8342a;
  --danger-soft: #fbeae8;
  --radius: 14px;
  --radius-sm: 10px;
  --shadow-sm: 0 1px 2px rgba(23, 33, 29, .05);
  --shadow-md: 0 10px 30px -12px rgba(23, 33, 29, .18), 0 2px 6px rgba(23, 33, 29, .04);
  --shadow-lg: 0 30px 70px -20px rgba(23, 33, 29, .35);
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  display: flex;
  min-height: 100vh;
}

h1, h2, h3, h4, p, figure { margin: 0; }

button, input, select, textarea { font: inherit; color: inherit; }

a { color: var(--brand); text-decoration: none; }

svg { display: block; }

